UPDATE lessons SET title='Year 3, Week 9, Lesson 1: Diagrams, graphs and captions', data=json_patch(data,'{"child_mission":"Information visuals each have a purpose: diagrams explain parts or processes, graphs display quantities, and captions help interpret what is shown.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same strategy to an unfamiliar topic or audience, then compare the effect of two different choices.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nIf you want to compare the number of birds seen in three gardens, choose a labelled diagram or a bar graph and justify.\n\nFEEDBACK\nA bar graph clearly compares quantities across gardens. A labelled drawing may identify body parts but does not display the counts as effectively.\n\nCHECK\nA decorative picture without a useful label or caption is not evidence for a numerical claim.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nCreate two static visual plans about a topic: a labelled process diagram with arrows and a small bar-graph dataset containing three categories and accurate counts. Write a precise caption for each; state the main information each reader should learn.\n\nWrite a short reflection describing one specific revision you made and why.","interactive_activities":null,"learning_area":"English","learning_intention":"Information visuals each have a purpose: diagrams explain parts or processes, graphs display quantities, and captions help interpret what is shown.","lesson_number":1,"lesson_role":"Reading","materials":["Paper or typed answer space","Pencil"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["EN2-RECOM-01"],"parent_notes":"Parent: M